refentry.refsect1:
&reftitle.description;
stringrtrim stringstring stringcharacters" \f\n\r\t\v\x00"
यो function ले string को end from whitespace (वा अन्य क्यारेक्टरहरू) हटाइएको string return गर्दछ। दोस्रो parameter बिना, rtrim ले यी characters हटाउनेछ: &strings.stripped.characters;

&reftitle.changelog;





    &Version;
    &Description;





    8.6.0
    Form feed character ("\f") लाई characters को default value मा थपिएको थियो।

  &reftitle.examples;



    rtrim को प्रयोगको उदाहरण


<?php

$text = "\t\tThese are a few words :) ...  ";
$binary = "\x09Example string\x0A";
$hello  = "Hello World";
var_dump($text, $binary, $hello);

print "\n";

$trimmed = rtrim($text);
var_dump($trimmed);

$trimmed = rtrim($text, " \t.");
var_dump($trimmed);

$trimmed = rtrim($hello, "Hdle");
var_dump($trimmed);

// trim the ASCII control characters at the end of $binary
// (from 0 to 31 inclusive)
$clean = rtrim($binary, "\x00..\x1F");
var_dump($clean);

?>


    &example.outputs;


string(32) "		These are a few words :) ...  "
string(16) "	Example string
"
string(11) "Hello World"

string(30) "		These are a few words :) ..."
string(26) "		These are a few words :)"
string(9) "Hello Wor"
string(15) "	Example string"
